     1	package hotel.reservations;
     2	
     3	import hotel.rooms.Room;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	import java.time.DayOfWeek;
     7	import java.time.LocalDate;
     8	import java.time.Month;
     9	
    10	/**
    11	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    12	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
    13	 * (half-even) at every step.
    14	 */
    15	public final class PriceCalculator {
    16	
    17	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    18	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    19	    static final BigDecimal CORPORATE_TECNOSUL_DISCOUNT = new BigDecimal("0.12");
    20	    static final BigDecimal CORPORATE_AGROVALE_DISCOUNT = new BigDecimal("0.18");
    21	    static final BigDecimal CORPORATE_FARMAVIDA_DISCOUNT = new BigDecimal("0.25");
    22	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
    23	    static final BigDecimal WEEKEND_PACKAGE_DISCOUNT = new BigDecimal("0.50");
    24	
    25	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
    26	        return calculate(room, checkIn, checkOut, ratePlan, null);
    27	    }
    28	
    29	    public Price calculate(
    30	            Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
    31	        if (ratePlan == RatePlan.WEEKEND_PACKAGE) {
    32	            return calculateWeekendPackage(room, checkIn, checkOut);
    33	        }
    34	        if (ratePlan == RatePlan.LONG_STAY) {
    35	            return calculateLongStay(room, checkIn, checkOut);
    36	        }
    37	        int nights = 0;
    38	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    39	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    40	            subtotal = subtotal.add(nightPrice(room, night));
    41	            nights++;
    42	        }
    43	        BigDecimal discount = switch (ratePlan) {
    44	            case STANDARD -> cents(BigDecimal.ZERO);
    45	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    46	            case CORPORATE -> cents(subtotal.multiply(corporateDiscount(companyCode)));
    47	            case WEEKEND_PACKAGE, LONG_STAY -> cents(BigDecimal.ZERO);
    48	        };
    49	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    50	    }
    51	
    52	    private Price calculateWeekendPackage(Room room, LocalDate checkIn, LocalDate checkOut) {
    53	        BigDecimal packagePrice = weekendPackagePrice(room.type());
    54	        return new Price(2, packagePrice, cents(BigDecimal.ZERO), packagePrice);
    55	    }
    56	
    57	    private Price calculateLongStay(Room room, LocalDate checkIn, LocalDate checkOut) {
    58	        int nights = 0;
    59	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    60	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    61	            subtotal = subtotal.add(nightPrice(room, night));
    62	            nights++;
    63	        }
    64	        BigDecimal discount = cents(subtotal.multiply(LONG_STAY_DISCOUNT));
    65	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    66	    }
    67	
    68	    private BigDecimal corporateDiscount(String companyCode) {
    69	        return switch (companyCode) {
    70	            case "TECNOSUL" -> CORPORATE_TECNOSUL_DISCOUNT;
    71	            case "AGROVALE" -> CORPORATE_AGROVALE_DISCOUNT;
    72	            case "FARMAVIDA" -> CORPORATE_FARMAVIDA_DISCOUNT;
    73	            default -> BigDecimal.ZERO;
    74	        };
    75	    }
    76	
    77	    private BigDecimal weekendPackagePrice(hotel.rooms.RoomType roomType) {
    78	        return switch (roomType) {
    79	            case STANDARD -> new BigDecimal("520.00");
    80	            case DELUXE -> new BigDecimal("820.00");
    81	            case SUITE -> new BigDecimal("1200.00");
    82	        };
    83	    }
    84	
    85	    BigDecimal nightPrice(Room room, LocalDate night) {
    86	        BigDecimal nightlyRate = room.nightlyRate();
    87	        if (isHighSeason(night)) {
    88	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    89	        }
    90	        return cents(nightlyRate);
    91	    }
    92	
    93	    /** High season: from December 15 to the end of February, and the whole of July. */
    94	    static boolean isHighSeason(LocalDate date) {
    95	        Month month = date.getMonth();
    96	        return month == Month.JANUARY
    97	                || month == Month.FEBRUARY
    98	                || month == Month.JULY
    99	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
   100	    }
   101	
   102	    static BigDecimal cents(BigDecimal value) {
   103	        return value.setScale(2, RoundingMode.HALF_EVEN);
   104	    }
   105	}
   106	package hotel.reservations;
   107	
   108	import hotel.documents.ReservationReceipt;
   109	import hotel.messages.EmailSender;
   110	import hotel.rooms.Room;
   111	import hotel.rooms.Rooms;
   112	import java.math.BigDecimal;
   113	import java.time.LocalDate;
   114	
   115	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
   116	public final class ReservationService {
   117	
   118	    static final String HOTEL_NAME = "Pousada Maré Alta";
   119	
   120	    private final Rooms rooms;
   121	    private final ReservationStore store;
   122	    private final PriceCalculator priceCalculator;
   123	    private final EmailSender emailSender;
   124	
   125	    public ReservationService(
   126	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
   127	        this.rooms = rooms;
   128	        this.store = store;
   129	        this.priceCalculator = priceCalculator;
   130	        this.emailSender = emailSender;
   131	    }
   132	
   133	    public synchronized Reservation create(NewReservation request) {
   134	        if (!request.checkOut().isAfter(request.checkIn())) {
   135	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
   136	        }
   137	        if (request.guests() < 1) {
   138	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
   139	        }
   140	        validateRatePlan(request);
   141	        Room room = rooms.find(request.roomNumber())
   142	                .orElseThrow(() -> new HotelException(
   143	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
   144	        if (request.guests() > room.capacity()) {
   145	            throw new HotelException(
   146	                    ErrorCode.CAPACITY_EXCEEDED,
   147	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
   148	        }
   149	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
   150	            throw new HotelException(
   151	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
   152	        }
   153	        Price price =
   154	                priceCalculator.calculate(
   155	                        room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
   156	        return store.add(request, price);
   157	    }
   158	
   159	    private void validateRatePlan(NewReservation request) {
   160	        switch (request.ratePlan()) {
   161	            case CORPORATE -> {
   162	                if (!isValidCorporateCode(request.companyCode())) {
   163	                    throw new HotelException(
   164	                            ErrorCode.INVALID_REQUEST, "invalid or missing company code for CORPORATE rate plan");
   165	                }
   166	            }
   167	            case WEEKEND_PACKAGE -> {
   168	                if (!isWeekendPackageValid(request.checkIn(), request.checkOut())) {
   169	                    throw new HotelException(
   170	                            ErrorCode.INVALID_REQUEST,
   171	                            "WEEKEND_PACKAGE must be Friday to Sunday, two nights only");
   172	                }
   173	            }
   174	            case LONG_STAY -> {
   175	                int nights = (int) (request.checkOut().toEpochDay() - request.checkIn().toEpochDay());
   176	                if (nights < 7) {
   177	                    throw new HotelException(
   178	                            ErrorCode.INVALID_REQUEST, "LONG_STAY requires at least 7 nights");
   179	                }
   180	            }
   181	            default -> {
   182	            }
   183	        }
   184	    }
   185	
   186	    private boolean isValidCorporateCode(String companyCode) {
   187	        return "TECNOSUL".equals(companyCode)
   188	                || "AGROVALE".equals(companyCode)
   189	                || "FARMAVIDA".equals(companyCode);
   190	    }
   191	
   192	    private boolean isWeekendPackageValid(LocalDate checkIn, LocalDate checkOut) {
   193	        return checkIn.getDayOfWeek() == java.time.DayOfWeek.FRIDAY
   194	                && checkOut.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
   195	                && checkOut.toEpochDay() - checkIn.toEpochDay() == 2;
   196	    }
   197	
   198	    public Reservation find(long reservationId) {
   199	        return store.find(reservationId)
   200	                .orElseThrow(() -> new HotelException(
   201	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
   202	    }
   203	
   204	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
   205	    public synchronized Reservation confirm(long reservationId) {
   206	        Reservation reservation = find(reservationId);
   207	        if (reservation.status() != ReservationStatus.PENDING) {
   208	            throw notAllowed(reservation, "confirm");
   209	        }
   210	        reservation.confirmPayment();
   211	        store.update(reservation);
   212	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
   213	        emailSender.send(
   214	                reservation.guest().email(),
   215	                "Reserva confirmada - " + HOTEL_NAME,
   216	                confirmationEmailBody(reservation, receipt));
   217	        return reservation;
   218	    }
   219	
   220	    /**
   221	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
   222	     * reservation was never paid, so nothing comes back).
   223	     */
   224	    public synchronized Reservation cancel(long reservationId) {
   225	        Reservation reservation = find(reservationId);
   226	        if (reservation.status() != ReservationStatus.PENDING
   227	                && reservation.status() != ReservationStatus.CONFIRMED) {
   228	            throw notAllowed(reservation, "cancel");
   229	        }
   230	        BigDecimal refund = switch (reservation.ratePlan()) {
   231	            case STANDARD, CORPORATE, LONG_STAY -> reservation.amountPaid();
   232	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
   233	            case WEEKEND_PACKAGE -> PriceCalculator.cents(reservation.amountPaid().multiply(PriceCalculator.WEEKEND_PACKAGE_DISCOUNT));
   234	        };
   235	        reservation.cancel(refund);
   236	        store.update(reservation);
   237	        return reservation;
   238	    }
   239	
   240	    public synchronized Reservation checkIn(long reservationId) {
   241	        Reservation reservation = find(reservationId);
   242	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   243	            throw notAllowed(reservation, "check in");
   244	        }
   245	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   246	        store.update(reservation);
   247	        return reservation;
   248	    }
   249	
   250	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   251	    public synchronized ReservationReceipt checkOut(long reservationId) {
   252	        Reservation reservation = find(reservationId);
   253	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   254	            throw notAllowed(reservation, "check out");
   255	        }
   256	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   257	        store.update(reservation);
   258	        return new ReservationReceipt(reservation, roomOf(reservation));
   259	    }
   260	
   261	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   262	    public ReservationReceipt receiptCopy(long reservationId) {
   263	        Reservation reservation = find(reservationId);
   264	        if (!reservation.isPaid()) {
   265	            throw notAllowed(reservation, "issue a receipt for");
   266	        }
   267	        return new ReservationReceipt(reservation, roomOf(reservation));
   268	    }
   269	
   270	    private Room roomOf(Reservation reservation) {
   271	        return rooms.find(reservation.roomNumber()).orElseThrow();
   272	    }
   273	
   274	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   275	        return "Olá, " + reservation.guest().name() + "!\n\n"
   276	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   277	                + receipt.text() + "\n"
   278	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   279	                + "Até breve!\n";
   280	    }
   281	
   282	    private static HotelException notAllowed(Reservation reservation, String operation) {
   283	        return new HotelException(
   284	                ErrorCode.OPERATION_NOT_ALLOWED,
   285	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   286	    }
   287	}
